entries[77616] = { ["name"] = "Dunkles Simulakrum", ["text"] = "Sofort\nBelegt einen Gegner mit dunkler Magie. Sobald der Gegner das nächste Mal Mana für einen Einzelzielzauber verbraucht, wird der Effekt ausgelöst, wodurch er den gewirkten Zauber kopiert und dem Todesritter einmalig zur Verfügung stellt. Bei Nichtspielerzielen werden lediglich einige wenige schädliche Zauber kopiert." }
