entries[77628] = { ["name"] = "Jungen Druiden retten", ["text"] = "5 Meter Reichweite\nWirken in 0.5 sek. 2 sek. Abklingzeit\nGreift nach einem hilflosen jungen Druiden im Hain von Thal'darah." }
entries[77629] = { ["name"] = "Jungen Druiden absetzen", ["text"] = "10 Meter Reichweite\nWirken in 0.5 sek. 10 sek. Abklingzeit\nSetzt einen geretteten jungen Druiden an der Hippogrpyhenstation an der Aussicht von Thal'darah ab." }
entries[77630] = { ["name"] = "Befehl über Thal'darahs Hippogryphen", ["text"] = "150 Meter Reichweite\nSofort\nKontrolliert Thal'darahs Hippogryphen! Ihr könnt nur im Kriegsnarbental, bei der Aussicht von Thal'darah, beim Steinkrallengipfel und beim Hain von Thal'darah fliegen." }
